-- ============================================================================
-- payer-rules-coverage-basis-medmutual.sql
--
-- Medical Mutual of Ohio answered NOTHING for coverage: 0 of 25 codes, an
-- empty code picker, exactly where Aetna and Anthem were before fe4f939.
--
-- WHAT WAS SEARCHED
-- Its own Provider Manual, October 2025 edition (Z6640 R10/25) -- 110 pages,
-- 425,714 characters of extracted text. NONE of the 25 codes appears in it.
-- That is the same result Aetna gave across all 919 of its live Clinical
-- Policy Bulletins, and it is not a research failure: a commercial plan's
-- coverage is contractual per benefit plan, so there is no per-code list to
-- find. Medical Mutual says so itself, which is what this seed records.
--
-- RETRIEVAL
-- medmutual.com refuses connections from both this workstation and the
-- production VPS -- not a 403, a TCP refusal, so the host is filtering by
-- network rather than blocking a bot. The manual was therefore read from the
-- Internet Archive snapshot of 2025-11-10. The rule cites the payer's OWN
-- canonical URL, because that is what a biller in Ohio should open; expect
-- scripts/recheck-source-drift.mjs to report it unreachable from our network,
-- which is a fact about us and not about the document.
--
-- WHAT THIS ASSERTS
-- Not that these codes are covered. That Medical Mutual publishes no
-- code-level coverage determination and states coverage is defined by the
-- individual policy. coverage_status 'varies' -- the picker badges it, sorts
-- it below genuinely covered codes, carries the citation, and the denial
-- scorer does not read it as coverage. The biller gets "plan-specific,
-- verify eligibility" with a document, instead of an empty list.
-- ============================================================================

BEGIN;

INSERT INTO source_document (id, payer_id, url, document_type, title, retrieved_at, content_hash, cms_license_token_used, source_metadata, extracted_at)
VALUES ('f2000000-0003-4000-8000-00000000b003'::uuid, 'a0000000-0000-4000-8000-000000000304'::uuid, 'https://www.medmutual.com/-/media/MedMutual/Files/Providers/Provider-Manual.pdf', 'provider_manual',
        'Medical Mutual of Ohio — Provider Manual (October 2025, Z6640 R10/25)',
        now(), 'sha256:0460ffb155e3c32ea6e4ad7a2fb152770b157f99bf4071634d44b9ceabf907bc',
        FALSE, '{"retrievedVia":"medmutual.com refuses TCP connections from our networks (workstation and VPS alike); read from the Internet Archive snapshot 20251110040317. The cited URL is the payer canonical one.","corpusChecked":"all 110 pages / 425,714 chars searched for the 25 palliative codes — zero hits"}'::jsonb, now())
