UPDATE payer_rule pr
   SET expiration_date = GREATEST(pr.effective_date, DATE '2025-10-01')
 WHERE pr.expiration_date IS NULL
   AND pr.payer_id = 'a0000000-0000-4000-8000-000000000304'::uuid
   AND pr.attribute = 'covered'
   AND pr.created_by <> 'extract:coverage-basis-medmutual-2026-08';

